def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, list] = {}
    history: list = []
    rejected: list[int] = []

    def parse_amount(token: str, positive: bool) -> int | None:
        if not token or any(c not in "0123456789" for c in token):
            return None
        n = int(token)
        if positive and n <= 0:
            return None
        return n

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False

        if verb == "open" and len(parts) == 3:
            name, n = parts[1], parse_amount(parts[2], False)
            if n is not None and name not in accounts:
                accounts[name] = [n, False]
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, n = parts[1], parse_amount(parts[2], True)
            if n is not None and name in accounts:
                accounts[name][0] += n
                history.append(("deposit", name, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, n = parts[1], parse_amount(parts[2], True)
            if (
                n is not None
                and name in accounts
                and not accounts[name][1]
                and accounts[name][0] >= n
            ):
                accounts[name][0] -= n
                history.append(("withdraw", name, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            src, dst, n = parts[1], parts[2], parse_amount(parts[3], True)
            if (
                n is not None
                and src != dst
                and src in accounts
                and dst in accounts
                and not accounts[src][1]
                and accounts[src][0] >= n
            ):
                accounts[src][0] -= n
                accounts[dst][0] += n
                history.append(("transfer", src, dst, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in accounts and not accounts[name][1]:
                accounts[name][1] = True
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in accounts and accounts[name][1]:
                accounts[name][1] = False
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1 and history:
            rec = history.pop()
            kind = rec[0]
            if kind == "open":
                del accounts[rec[1]]
            elif kind == "deposit":
                accounts[rec[1]][0] -= rec[2]
            elif kind == "withdraw":
                accounts[rec[1]][0] += rec[2]
            elif kind == "transfer":
                accounts[rec[1]][0] += rec[3]
                accounts[rec[2]][0] -= rec[3]
            elif kind == "freeze":
                accounts[rec[1]][1] = False
            else:
                accounts[rec[1]][1] = True
            ok = True

        if not ok:
            rejected.append(i)

    return {name: state[0] for name, state in accounts.items()}, rejected
